const app=document.querySelector('#app');
const posts=[
{id:0,category:'技术',date:'09.16',title:'让模型知道，它正身处沙箱',desc:'从一个权限边界，重新理解 Agent 与运行环境的关系。',tag:'AGENT ENGINEERING',time:'6 min',body:['写一个 Agent，往往从「把工具交给模型」开始。但工具能够被调用，并不代表模型理解自己所在的环境。','一个运行在沙箱里的工具会遇到明确的边界：哪些文件可以访问，哪些网络请求能够发出，哪些操作需要交给宿主环境。把这些条件变成清晰的上下文，模型才能做出与实际能力匹配的计划。','一个值得记录的设计问题','环境描述应该足够准确，也应该足够简短。与其罗列所有实现细节，不如让它回答三个问题：我在哪里？我能做什么？遇到边界时应该怎么办？','这也是个人博客值得保留的部分：不仅记录最终代码，也记录那些改变了你理解方式的小问题。']},
{id:1,category:'技术',date:'08.22',title:'上下文不是一个静止的数字',desc:'一次关于锚点、增量，以及「现在」的排查。',tag:'BUILDING IN PUBLIC',time:'8 min',body:['最初的实现看起来很合理：只要有模型返回的 usage，就直接使用它作为上下文长度。','但这个数字描述的是上一次调用。在那之后，新的工具结果与对话仍然在增加。如果计量始终停留在旧锚点，增长就会悄悄消失。','让测量追上变化','更合适的思路，是把最近一次真实 usage 当成锚点，再加上锚点之后新增内容的估算。真实值和估计值各自负责自己最擅长的部分。','排查问题的转折点，往往不是又写了多少代码，而是终于问清楚：这个变量究竟描述哪个时间点？']},
{id:2,category:'技术',date:'08.21',title:'一个编码 Bug 的漫长下午',desc:'当 UTF-8 遇上 Shell，问题究竟藏在哪一层？',tag:'DEBUGGING NOTES',time:'7 min',body:['当相同的文本在不同运行路径下出现不同结果，第一反应通常是怀疑业务逻辑。但问题也可能发生在文本穿越进程边界的时候。','从输入、序列化到 Shell，再到目标进程，每一次转换都值得单独观察。缩小复现范围，让每一步的输入输出都可见，比在整个系统里盲目修改更有效。','给未来的自己留一条路','记录最小复现、当时的假设，以及最终排除假设的证据。这些内容比一句「修复了编码问题」更有价值。','这篇演示文章围绕已有日志主题重新编写，正式博客可以替换为完整的原始排障记录。']},
{id:3,category:'随笔',date:'08.18',title:'给想法留一块慢慢生长的地方',desc:'不是每一个念头，都需要立即成为一篇完整的文章。',tag:'LIFE & NOTES',time:'4 min',body:['有些想法适合写成文章，有些只需要一个标题、几句观察和一条链接。它们不必在同一天成熟。','我喜欢把个人网站想象成一个可以反复回来的地方。今天种下一条问题，下个月补上一段答案。早期的困惑不需要被删除，它本身就是思考的痕迹。','允许未完成','把笔记标记为「种子」「生长中」「常青」，是在邀请读者用不同的方式阅读：这里有结论，也有仍然开放的提问。','也许一个好的个人博客，并不需要显得无所不知。它只需要诚实地展示，一个人正在关心什么。']},
{id:4,category:'随笔',date:'08.12',title:'好的工具，让人忘记工具本身',desc:'一点关于界面、注意力和日常工作的观察。',tag:'DESIGN NOTES',time:'5 min',body:['我们常用功能数量评价工具，却很少计算切换注意力的成本。每一个弹窗、每一处不确定的状态，都需要用户额外理解。','我更喜欢那些能清楚表达当前状态的界面：发生了什么，接下来能做什么，操作是否完成。','让界面有自己的节奏','把高频操作放在触手可及的位置，把说明写在真正需要它的地方，让细节帮助用户继续工作。','在博客里也是一样。先让内容清楚、文字舒适，再去寻找属于自己的视觉语气。']}
];
const landscape=`<svg class="landscape" viewBox="0 0 540 430" role="img" aria-label="原创几何插画：阳光穿过拱门，照向层叠的山丘"><defs><clipPath id="scene"><rect width="540" height="430" rx="2"/></clipPath><pattern id="grain" width="7" height="7" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r=".45" fill="#292f24" opacity=".16"/></pattern></defs><g clip-path="url(#scene)"><path fill="#d5d7be" d="M0 0h540v430H0z"/><circle cx="361" cy="114" r="51" fill="#dbaa66"/><path d="M0 327Q160 144 324 281T580 229V430H0Z" fill="#9ba282"/><path d="M0 395Q176 279 344 350T580 302V430H0Z" fill="#727e58"/><path d="M73 430V153a116 116 0 01232 0v277h-44V157a72 72 0 00-144 0v273Z" fill="#edebda"/><path d="M73 430V153a116 116 0 01232 0v277h-16V153a100 100 0 00-200 0v277Z" fill="#e3e0cc"/><path d="M117 318l144-78v190H117z" fill="#5b6847"/><path d="M117 318l144-78 158 190H229Z" fill="#b9bb93"/><path d="M0 0h540v430H0z" fill="url(#grain)"/><path d="M441 323v-84m0 36q-35-2-37-34 32-3 37 34m0-15q29-7 31-36-27 1-31 36" fill="none" stroke="#596a4d" stroke-width="3"/><path d="M400 374h105" stroke="#5c6848"/><text x="24" y="32" fill="#636b4f" font-family="monospace" font-size="9" letter-spacing="2">A PLACE FOR THOUGHTS</text></g></svg>`;
const mini=`<svg viewBox="0 0 150 150" aria-hidden="true"><g fill="none" stroke="#7d8967" stroke-width="1"><path d="M22 103l53-31 53 31-53 31zM22 82l53-31 53 31-53 31zM22 61l53-31 53 31-53 31z"/><path d="M75 30v105M22 61v42M128 61v42" stroke-dasharray="3 3"/></g><circle cx="75" cy="50" r="9" fill="#c0a86e"/></svg>`;
const plant=`<svg class="plant" viewBox="0 0 480 320" role="img" aria-label="原创植物线稿：三株形态不同的小树在思考的土壤里生长"><g fill="none" stroke="#889977" stroke-width="1.2"><ellipse cx="245" cy="275" rx="190" ry="22" stroke-dasharray="2 6"/><path d="M236 270q-5-80 13-190m-9 108q-60-25-69-74m70 51q48-12 70-60m-68 34q-27-24-34-56"/><path d="M166 109q-16-42-44-31-6 32 44 31M178 136q-47-29-59-5 15 28 59 5M243 133q-50-42-33-67 32 13 33 67M248 97q-20-48 5-67 24 24-5 67M267 148q3-50 41-51 3 28-41 51M293 120q0-37 34-41 11 28-34 41M239 211q-41-8-56-43 33-15 56 43M242 232q42-47 62-28-7 31-62 28" fill="#e0e6ce"/><path d="M106 266q-10-33 0-65m0 24q-33-5-28-29 29 0 28 29m0 19q27-15 27-37-26-3-27 37" fill="#e4e9d7"/><path d="M370 268V145m0 76q-32-27-28-43 27 4 28 43m0-23q38-22 28-46-25 12-28 46"/><circle cx="370" cy="139" r="17" fill="#dfc685" stroke="#b3ab7c"/><path d="M346 138h48m-24-24v48"/><path d="M168 286h135M78 281h42M341 285h48"/></g><g font-family="Georgia,serif" font-size="12" fill="#8c977c" font-style="italic"><text x="50" y="172" transform="rotate(-9 50 172)">a small idea</text><text x="303" y="53" transform="rotate(6 303 53)">always growing</text></g></svg>`;
const graph=`<svg viewBox="0 0 440 255" role="img" aria-label="Agent 实验示意图：输入经过上下文、模型和工具循环后输出"><defs><pattern id="grid" width="22" height="22" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r=".6" fill="#465048"/></pattern></defs><rect width="440" height="255" fill="url(#grid)"/><g fill="none" stroke="#809765"><path d="M76 131h77m119 0h90M216 100V58H350v45M216 160v45H94v-41"/><path d="M145 126l8 5-8 5m208-10l8 5-8 5M345 95l5 8 5-8"/></g><g fill="#222a24" stroke="#61734e"><rect x="27" y="108" width="68" height="46" rx="6"/><rect x="152" y="101" width="120" height="60" rx="7"/><rect x="334" y="108" width="79" height="46" rx="6"/></g><g font-family="monospace" font-size="10" text-anchor="middle" fill="#b6c7a5"><text x="61" y="135">INPUT</text><text x="212" y="136" fill="#d0f99d" font-size="13">AGENT</text><text x="374" y="135">OUTPUT</text><text x="287" y="48" fill="#7c877a" font-size="8">TOOL CALL</text><text x="150" y="226" fill="#7c877a" font-size="8">CONTEXT LOOP</text></g><circle cx="310" cy="58" r="4" fill="#c1f18b"/><circle cx="125" cy="205" r="3" fill="#c1f18b"/></svg>`;
const directions={editorial:{name:'纸感编辑部',en:'THE QUIET EDITORIAL',colors:['#f0f0e7','#ced0bf','#727e58','#dbaa66'],intro:'像翻开一本小而认真的独立杂志。用有呼吸感的排版，让技术记录也值得慢慢读。',points:['骨架：宽幅刊头 + 双栏开场 + 一篇精选与短文章列表。','字体：中文宋体承担标题，细小的等宽字呈现日期与栏目。','适合：长文、个人随笔，以及有故事线的技术复盘。'],ref:'Maggie Appleton',url:'https://maggieappleton.com/',learn:'借鉴她将技术与视觉叙事放在一起的内容思路；纸感色彩、几何插画和版式为本示例原创。'},minimal:{name:'极简开发者',en:'LESS, BUT PERSONAL',colors:['#fcfcfc','#e9e9e9','#839c8d','#30363c'],intro:'把自己放在首页，把内容放在眼前。少一点装饰，让长期写作自然成为网站的主角。',points:['骨架：窄内容宽度 + 一段自我介绍 + 按日期排列的文章。','阅读：轻量分类与搜索，标题、摘要、日期有清楚的层次。','适合：开发日志、开源作者主页，以及稳定更新的技术博客。'],ref:'Anthony Fu',url:'https://antfu.me/',learn:'借鉴个人介绍、项目与文章并列的内容组织；中文布局与示例视觉独立设计。'},garden:{name:'数字花园',en:'A GARDEN OF IDEAS',colors:['#faf7ee','#e0e6ce','#889977','#dfc685'],intro:'允许内容未完成，也允许它慢慢变化。读者进入的是一个持续生长的思考空间。',points:['骨架：植物插画开场 + 生长阶段索引 + 手札式笔记。','内容：以种子、生长中、常青区分想法的成熟程度。','适合：学习笔记、跨学科阅读，以及尚无定论的长期问题。'],ref:'Maggie Appleton',url:'https://maggieappleton.com/',learn:'借鉴 Digital Garden 将未完成笔记和成熟文章共同呈现的理念；植物线稿为本示例原创。'},lab:{name:'深色实验室',en:'IDEAS, UNDER CONSTRUCTION',colors:['#14161a','#303238','#c3ee82','#93979c'],intro:'像推开一个独立开发者的工作室。让过程、实验与技术图解共同构成个人风格。',points:['骨架：清晰的宣言 + Agent 流程图 + 实验卡片。','视觉：石墨黑与柔和荧光绿，网格和等宽字只用于技术信息。','适合：AI Agent、工具开发、交互演示和实验型文章。'],ref:'Josh W. Comeau',url:'https://www.joshwcomeau.com/',learn:'借鉴用演示与图解解释技术的表达方法；此处深色实验室视觉并非对原站样式的复刻。'}};
let current='editorial';let filter='全部';let query='';let gardenFilter='全部';
const links=()=>`<div class="blog-links"><a href="#" data-action="articles">文章</a><a href="#" data-action="about">关于我</a><a href="#" data-action="notes" class="optional">灵感来源 ↗</a></div>`;
const about=()=>`<section class="about-inline" id="about-inline" hidden><b>你好，我是 OMEN。</b><br>这里是一个围绕代码、工具与生活观察的个人博客示例。最近在探索 AI Agent，喜欢把构建过程中的问题与发现记录下来。页面使用演示文案，部分技术主题来自工作区已有日志。</section>`;
const post=(id,cls='text-post')=>`<button class="post-button ${cls}" data-post="${id}"><span class="meta">${posts[id].date} / ${posts[id].tag}</span><h3 class="serif">${posts[id].title}</h3></button>`;
function editorial(){return `<section class="editorial fade-in"><div class="shell"><header class="blog-nav"><a href="#editorial" class="logo serif">行间<em>·</em><span>OMEN'S JOURNAL</span></a>${links()}</header>${about()}<section class="hero"><div><span class="eyebrow">ISSUE 001 — NOTES ON MAKING & LIVING</span><h1 class="serif">在代码与生活之间，<br>留一点<em>思考的空白。</em></h1><p>你好，我是 OMEN。一个爱折腾的开发者。<br>这里收集构建中的发现、未完成的想法，和日常里值得记住的事。</p><a class="arrow-link" href="#" data-action="articles">翻开最近的记录 <span>↗</span></a></div><div class="art-frame">${landscape}<div class="art-stamp">STAY<br>CURIOUS<br>✳</div><div class="art-caption"><span>FIG. 01 — A LITTLE ROOM TO THINK</span><span>2026</span></div></div></section><section id="articles"><div class="section-label"><h2>最近的书写 <span>RECENT ENTRIES</span></h2><a href="#minimal">全部文章 ↗</a></div><div class="editorial-grid"><button class="post-button featured" data-post="1"><div class="mini-art">${mini}</div><div><span class="meta">01 / BUILDING IN PUBLIC</span><h3 class="serif">上下文不是<br>一个静止的数字</h3><p class="excerpt">一次关于锚点、增量，以及「现在」的排查。</p><span class="meta">2026.08.22 · 8 MIN READ ↗</span></div></button><div>${post(0)}${post(3)}</div></div></section><div class="editorial-bottom"><span>正在探索 <b>↗ AI Agent 与人与工具的关系</b></span><span>写作，是另一种思考。</span></div></div></section>`}
function minimal(){return `<section class="minimal fade-in"><div class="shell"><header class="blog-nav"><a href="#minimal" class="logo">omen<span> / personal space</span></a>${links()}</header>${about()}<section class="hero"><svg class="doodle" viewBox="0 0 150 150" aria-hidden="true"><g fill="none" stroke="currentColor" stroke-width="1.2"><ellipse cx="75" cy="75" rx="60" ry="26" transform="rotate(35 75 75)"/><ellipse cx="75" cy="75" rx="60" ry="26" transform="rotate(95 75 75)"/><ellipse cx="75" cy="75" rx="60" ry="26" transform="rotate(155 75 75)"/></g><circle cx="75" cy="75" r="4" fill="#9caf9e"/></svg><h1>Hey, I'm Omen<span class="muted">.</span></h1><p>写代码，也写一些关于代码之外的东西。<br>正在探索 <a href="#lab">AI Agent</a>、开源工具，以及更自在的数字生活。<br>喜欢把复杂的问题拆开，再慢慢理解它。</p><div class="status">CURRENTLY BUILDING · agent lite</div></section><section id="articles"><div class="section-label"><h2>书写 <span>WRITING</span></h2><span class="meta">2026</span></div><div class="filter-row">${['全部','技术','随笔'].map(x=>`<button data-filter="${x}" class="${x===filter?'active':''}" aria-pressed="${x===filter}">${x}</button>`).join('')}<input id="search" aria-label="搜索文章" placeholder="搜索文章 ↵" type="search" autocomplete="off"></div><div id="post-list"></div></section><a href="#lab" class="project-strip"><span>↳ 小项目，长时间的好奇心。<small>agent lite · 从零理解一个 Agent 如何工作</small></span><span>去实验室 ↗</span></a></div></section>`}
function garden(){return `<section class="garden fade-in"><div class="shell"><header class="blog-nav"><a href="#garden" class="logo">未完成花园<span>A DIGITAL GARDEN</span></a>${links()}</header>${about()}<section class="hero"><div><span class="eyebrow">TENDED BY OMEN · EST. 2026</span><h1 class="serif">有些想法，<br>需要一点时间长大。</h1><p>欢迎来到我的数字花园。<br>这里有刚冒芽的问题、持续生长的笔记，<br>也有偶尔开花的长文。随便走走，不必按顺序。</p></div><div>${plant}<div class="handnote">小心，脚边有新长出来的想法。</div></div></section><section class="garden-layout" id="articles"><aside class="garden-aside"><h2>沿着小径探索</h2>${[['全部','04'],['种子','01'],['生长中','02'],['常青','01']].map(([x,n])=>`<button data-growth="${x}" class="${gardenFilter===x?'active':''}" aria-pressed="${gardenFilter===x}"><span>${x==='全部'?'✳':x==='种子'?'·':x==='生长中'?'⚘':'❋'} ${x}</span><span>${n}</span></button>`).join('')}<p>不以发布时间排序，<br>而以好奇心相连。<br><br>每次回来，都有一点变化。</p></aside><div class="garden-cards" id="garden-cards"></div></section></div></section>`}
function lab(){return `<section class="lab fade-in"><div class="shell"><header class="blog-nav"><a href="#lab" class="logo"><b>[</b> OMEN <b>]</b><span> / LAB</span></a>${links()}</header>${about()}<section class="hero"><div><span class="eyebrow">INDEPENDENT DEVELOPER / CURIOUS HUMAN</span><h1>把好奇心，<br>变成<span>能运行的东西。</span></h1><p>关于 AI Agent、代码与创造的小型实验室。<br>记录构建过程，也记录那些意料之外的发现。</p><div class="status">SYSTEM ONLINE · ALWAYS EXPERIMENTING</div></div><div class="terminal-art"><div class="terminal-top"><span>● ● ●</span>agent-runtime.ts</div>${graph}<div class="terminal-footer"><span>↳ curiosity → experiment → insight</span><span>v.001</span></div></div></section><section id="articles"><div class="section-label"><h2>实验记录 <span>FIELD NOTES</span></h2><a href="#minimal">VIEW ARCHIVE ↗</a></div><div class="lab-grid">${[0,1,2].map((id,i)=>`<button class="post-button lab-card" data-post="${id}"><div class="card-art">${['[ ↗ ] → ◇','T = α + Δ','&lt;/&gt; UTF-8'][i]}</div><div class="card-content"><span class="meta">EXP. 00${i+1} / ${posts[id].date}</span><h3>${posts[id].title}</h3><p>${posts[id].desc}</p><span class="meta">READ THE LOG ↗</span></div></button>`).join('')}</div></section><div class="lab-bottom"><span>BUILD. BREAK. UNDERSTAND. REPEAT.</span><span>© 2026 OMEN / MADE WITH CURIOSITY</span></div></div></section>`}
function listPosts(){const list=posts.filter(p=>(filter==='全部'||p.category===filter)&&`${p.title}${p.desc}`.toLowerCase().includes(query.toLowerCase()));document.querySelector('#post-list').innerHTML=list.length?list.map(p=>`<button class="post-button minimal-post" data-post="${p.id}"><time>${p.date}</time><div><h3>${p.title}</h3><p>${p.desc}</p></div><span>${p.time} ↗</span></button>`).join(''):'<p class="empty" role="status">暂时没有匹配的文章，换个关键词试试。</p>'}
const growths=['常青','生长中','种子','生长中'];const gardenIds=[3,1,4,0];
function gardenCards(){document.querySelector('#garden-cards').innerHTML=gardenIds.map((id,i)=>({p:posts[id],g:growths[i]})).filter(x=>gardenFilter==='全部'||x.g===gardenFilter).map(({p,g})=>`<button class="post-button garden-card" data-post="${p.id}"><span class="growth">${g==='种子'?'·':g==='常青'?'❋':'⚘'} ${g}</span><h3>${p.title}</h3><p>${p.desc}</p><div class="card-bottom"><span>${p.category==='技术'?'#构建笔记':'#思考碎片'}</span><span>${p.date} ↗</span></div></button>`).join('')}
function render(){current=location.hash.slice(1);if(!directions[current])current='editorial';document.querySelectorAll('[data-theme]').forEach(a=>{a.classList.toggle('active',a.dataset.theme===current);if(a.dataset.theme===current)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});app.innerHTML=({editorial,minimal,garden,lab}[current])();if(current==='minimal'){document.querySelector('#search').value=query;listPosts()}if(current==='garden')gardenCards();document.title=`${directions[current].name} · 博客灵感集`;favoriteLabel()}
function showNotes(){const d=directions[current];document.querySelector('#notes-content').innerHTML=`<span class="eyebrow">DESIGN STUDY / ${d.en}</span><h2>${d.name}</h2><p>${d.intro}</p><div class="swatches">${d.colors.map(c=>`<span style="background:${c}" title="${c}"></span>`).join('')}</div><h3>你可以借鉴什么</h3><ul>${d.points.map(p=>`<li>${p}</li>`).join('')}</ul><h3>参考与转化</h3><p><a href="${d.url}" target="_blank" rel="noopener noreferrer">${d.ref} ↗</a><br>${d.learn}</p><p>所有方案使用演示内容；技术主题参考了工作区的 Agent 开发日志。文章弹窗展示重新编写的短文，不等同于原文全文。</p>`;document.querySelector('#notes').showModal()}
function showPost(id){const p=posts[id];document.querySelector('#reader-content').innerHTML=`<span class="eyebrow">${p.tag} / 2026.${p.date}</span><h2>${p.title}</h2><p>${p.desc} · ${p.time}</p><blockquote>本文为布局与阅读体验示例，围绕博客主题重新编写。</blockquote>${p.body.map((t,i)=>i===2?`<h3>${t}</h3>`:`<p>${t}</p>`).join('')}<p class="meta">OMEN'S JOURNAL · 保持好奇，继续记录。</p>`;document.querySelector('#reader').showModal()}
function favoriteLabel(){let selected=false;try{selected=JSON.parse(localStorage.getItem('blog-favorites')||'[]').includes(current)}catch{}const b=document.querySelector('#favorite');b.textContent=selected?'♥ 已收藏这个方向':'♡ 收藏这个方向';b.setAttribute('aria-pressed',String(selected))}
document.addEventListener('click',e=>{const postButton=e.target.closest('[data-post]');if(postButton)showPost(+postButton.dataset.post);const filterButton=e.target.closest('[data-filter]');if(filterButton){filter=filterButton.dataset.filter;document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b.dataset.filter===filter);b.setAttribute('aria-pressed',b.dataset.filter===filter)});listPosts()}const growth=e.target.closest('[data-growth]');if(growth){gardenFilter=growth.dataset.growth;document.querySelectorAll('[data-growth]').forEach(b=>{b.classList.toggle('active',b.dataset.growth===gardenFilter);b.setAttribute('aria-pressed',b.dataset.growth===gardenFilter)});gardenCards()}const action=e.target.closest('[data-action]');if(action){e.preventDefault();if(action.dataset.action==='articles')document.querySelector('#articles').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});if(action.dataset.action==='about'){const box=document.querySelector('#about-inline');box.hidden=!box.hidden;action.setAttribute('aria-expanded',!box.hidden)}if(action.dataset.action==='notes')showNotes()}if(e.target.closest('.close'))e.target.closest('dialog').close()});
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;listPosts()}});
document.querySelector('#show-notes').addEventListener('click',showNotes);
document.querySelector('#favorite').addEventListener('click',()=>{try{let list=JSON.parse(localStorage.getItem('blog-favorites')||'[]');list=list.includes(current)?list.filter(x=>x!==current):[...list,current];localStorage.setItem('blog-favorites',JSON.stringify(list));favoriteLabel()}catch{document.querySelector('#favorite').textContent='当前浏览器无法保存收藏'}});
document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});render();
